function busiestYear(logs: number[][]): number {
  let bestYear = 1950, bestCount = 0;
  for (let y = 1950; y <= 2050; y++) {
    let count = 0;
    for (const [b, d] of logs) if (b <= y && y < d) count++;
    if (count > bestCount) { bestCount = count; bestYear = y; }
  }
  return bestYear;
}

