function busiestYear(logs: number[][]): number {
  const delta = new Array(2051 - 1950).fill(0);
  for (const [b, d] of logs) {
    delta[b - 1950]++;
    delta[d - 1950]--;
  }
  let alive = 0, best = 0, bestYear = 1950;
  for (let i = 0; i < delta.length; i++) {
    alive += delta[i];
    if (alive > best) { best = alive; bestYear = 1950 + i; }
  }
  return bestYear;
}

